    resolved: items.filter((t) => t.status === 'resolved').length,
  }
40→})

function statusLabel(s) {
  return (
    {
      open: '待处理',
      in_progress: '进行中',
      resolved: '已闭环',
      cancelled: '已取消',
    }[s] || s
50→  )
}

function fmtTime(v) {
  if (!v) return '—'
