/* —— Plugin center —— */
.plugin-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
}
.plugin-card { display: flex; flex-direction: column; gap: 10px; }
.plugin-head {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 12px;
}
.plugin-name { font-size: 15px; font-weight: 700; }
.plugin-desc {
  margin: 0;
  font-size: 13px;
  color: var(--muted);
  line-height: 1.55;
  flex: 1;
}
.badge-status {
  flex-shrink: 0;
  border-radius: 999px;
  padding: 3px 10px;
  font-size: 12px;
  font-weight: 600;
  white-space: nowrap;
}
.badge-status.ready { background: #d1fae5; color: var(--ok); }
.badge-status.building { background: #ffedd5; color: var(--warn); }
.badge-status.pending { background: #dbeafe; color: #1d4ed8; }
.badge-status.planned { background: #e5e7eb; color: #4b5563; }

/* —— Shipping —— */
.pipeline {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
}
.pipe-step {
  display: flex;
  gap: 10px;
  align-items: flex-start;
  padding: 12px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: #f8fafc;
}
.pipe-num {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: var(--primary);
  color: #fff;
  display: grid;
  place-items: center;
