content.oldText:
async function triggerFeishu() {
  error.value = ''
  syncMsg.value = ''
  loading.value = true
  try {
    const r = await api('/api/v1/export/feishu', {
      method: 'POST',
      body: { table_key: 'tasks', mode: 'incremental' },
    })
    syncMsg.value = `已入队飞书同步 job: ${r.job_id}`
  } catch (e) {
    error.value = e.message
  } finally {
    loading.value = false
  }
}

content.newText:
async function triggerFeishu() {
  error.value = ''
  syncMsg.value = ''
  loading.value = true
  try {
    const r = await api('/api/v1/export/feishu', {
      method: 'POST',
      body: { table_key: 'tasks', mode: 'incremental' },
    })
    syncMsg.value = `已入队飞书同步 job: ${r.job_id}`
  } catch (e) {
    error.value = e.message
  } finally {
    loading.value = false
  }
}

function pluginStatusLabel(s) {
  return s
}

function generateAiReport() {
  error.value = ''
  const tpl = aiReportTemplates.find((t) => t.id === aiForm.template)
  const rangeLabel =
    {
      yesterday: '昨日',
      last7: '近 7 天',
      last30: '近 30 天',
    }[aiForm.range] || aiForm.range

  const openN = stats.value.open
  const doingN = stats.value.doing
  const totalN = stats.value.total
  const shopN = stats.value.shops
  const platforms = platformTaskStats.value
    .map((p) => `${p.platform}: ${p.count}`)
    .join(' · ')

  aiMsg.value = [
    `【${tpl?.name || 'AI 报表'}】${rangeLabel}`,
    `范围：${tpl?.scope || '全平台'}`,
    `异常任务 ${totalN} 条（待处理 ${openN} / 进行中 ${doingN}），店铺 ${shopN} 个。`,
    platforms ? `分平台：${platforms}` : '分平台：暂无数据',
    aiForm.note ? `补充说明：${aiForm.note}` : '',
    '',
    '（Phase0 演示：基于中心库任务/店铺汇总生成预览，完整 LLM 分析与推送将在后续接入。）',
  ]
    .filter(Boolean)
    .join('\n')
}

