FileContent.raw_output:
/* —— Shell: left nav + right content —— */
.app-layout {
  display: flex;
  min-height: 100vh;
  height: 100%;
}

.sidebar {
  width: var(--sidebar-w);
  flex: 0 0 var(--sidebar-w);
  background: linear-gradient(180deg, #0f3d3a 0%, #0a2e2b 100%);
  color: var(--sidebar-text);
  display: flex;
  flex-direction: column;
  min-height: 100vh;
  position: sticky;
  top: 0;
  align-self: flex-start;
  height: 100vh;
}

.sidebar-brand {
  padding: 22px 18px 18px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
}
.sidebar-brand .logo {
  font-size: 17px;
  font-weight: 700;
  letter-spacing: 0.04em;
  color: #fff;
}
.sidebar-brand .tag {
  margin-top: 6px;
  font-size: 12px;
  color: var(--sidebar-muted);
}

.sidebar-nav {
  flex: 1;
  padding: 10px 10px 16px;
  display: flex;
  flex-direction: column;
  gap: 2px;
  overflow-y: auto;
}

.nav-section-label {
  margin: 12px 10px 6px;
  font-size: 11px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--sidebar-muted);
  font-weight: 600;
}
.nav-section-label:first-child { margin-top: 4px; }

.nav-group { display: flex; flex-direction: column; gap: 2px; }

.nav-item {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  border: none;
  background: transparent;
  color: var(--sidebar-text);
  text-align: left;
  padding: 10px 12px;
  border-radius: 10px;
  cursor: pointer;
  font-size: 13.5px;
  transition: background 0.15s ease;
}
.nav-item:hover { background: var(--sidebar-hover); }
.nav-item.active {
  background: var(--sidebar-active);
  color: #fff;
  font-weight: 600;
  box-shadow: inset 3px 0 0 #2dd4bf;
}
.nav-item .icon {
  width: 20px;
  text-align: center;
  opacity: 0.9;
  font-size: 15px;
}
.nav-item .label { flex: 1; min-width: 0; }
.nav-item .chevron {
  font-size: 11px;
  color: var(--sidebar-muted);
  width: 14px;
  text-align: center;
}
.nav-item.nav-group-head.open {
  background: rgba(255, 255, 255, 0.06);
}
.nav-item.nav-group-head.active:not(.child) {
  box-shadow: none;
}
.platform-icon {

