rawInput.command:
Get-ScheduledTask | Where-Object {
  $i = $_.TaskName + ' ' + $_.TaskPath
  $a = ''
  try { $a = ((Get-ScheduledTaskInfo $_.TaskName -TaskPath $_.TaskPath -ErrorAction SilentlyContinue) | Out-String) } catch {}
  $i -match '驾驶|亚马逊|amazon|dashboard|qingquan|清泉' -or $_.TaskName -match '驾驶|亚马逊|amazon|dashboard'
} | Select-Object TaskName, TaskPath, State | Format-Table -AutoSize

Write-Output '--- actions containing 驾驶舱 or app.main ---'
Get-ScheduledTask | ForEach-Object {
  $t = $_
  foreach ($a in @($t.Actions)) {
    $line = "$($a.Execute) $($a.Arguments) $($a.WorkingDirectory)"
    if ($line -match '驾驶|亚马逊|app\.main|platform') {
      [PSCustomObject]@{
        TaskName = $t.TaskName
        Path = $t.TaskPath
        State = $t.State
        Execute = $a.Execute
        Arguments = $a.Arguments
        WorkingDirectory = $a.WorkingDirectory
      }
    }
  }
} | Format-List

Write-Output '--- project folder ---'
if (Test-Path 'E:\project\亚马逊平台驾驶舱') {
  Get-ChildItem 'E:\project\亚马逊平台驾驶舱' -Force | Select-Object Name, Mode, Length | Format-Table -AutoSize
}

